import{_ as t,o,c as a,a4 as n}from"./chunks/framework.DnJV5gp6.js";const h=JSON.parse('{"title":"Layout","description":"Placing views on screen with the flex layout engine — col/row, sizing, the at() escape hatch, and the collapse footguns.","frontmatter":{"title":"Layout","description":"Placing views on screen with the flex layout engine — col/row, sizing, the at() escape hatch, and the collapse footguns."},"headers":[],"relativePath":"guide/layout.md","filePath":"guide/layout.md"}'),s={name:"guide/layout.md"};function i(r,e,l,c,d,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h1><p>Placing views on screen with the flex layout engine — <code>col</code>/<code>row</code>, sizing, the <code>at()</code> escape hatch, and the collapse footguns.</p><div class="info custom-block"><p class="custom-block-title">This guide is being written</p><p>This page is a placeholder while the guide is authored. Follow its progress — and the outline of what it will cover — in <a href="https://github.com/blendsdk/jsvision/issues/146" target="_blank" rel="noreferrer">issue #146</a>.</p></div><h2 id="translated-action-groups" tabindex="-1">Translated action groups <a class="header-anchor" href="#translated-action-groups" aria-label="Permalink to &quot;Translated action groups&quot;">​</a></h2><p>Do not guess widths for translated dialog actions. A <code>Button</code> measures its natural caption in terminal display cells, so wide glyphs, combining characters, and accelerator markup are handled consistently. Use <code>measureButtonGroup()</code> to negotiate the viewport minimum for the complete action set, then pass the same unattached Buttons and options to <code>buttonGroup()</code>.</p><p>Group measurement uses the widest sibling for equal button widths. <code>maxColumns</code> preserves row-major ordering while wrapping equal-width buttons across multiple rows; use <code>buttonColumn()</code> for a vertical action set. When the preferred width does not fit, first expand the dialog or reduce <code>maxColumns</code>. An absolute rectangle remains a hard clipping bound at the terminal edge.</p><p>See <a href="/jsvision/pr-preview/pr-190/components/controls/button.html#sizing-layout">Button sizing and layout</a> for a copyable example and the single-parent ownership rule.</p>',7)])])}const g=t(s,[["render",i]]);export{h as __pageData,g as default};
